// Static nudge configuration
// Dynamic nudges are generated by useNudges hook
// This file contains the nudge display configuration and dismissed state helpers

export const NUDGE_TYPES = {
  alert: {
    label: 'Alert',
    color: '#CC0000',
    bg: 'rgba(204,0,0,0.08)',
    border: '#CC0000',
  },
  warning: {
    label: 'Warning',
    color: '#B8860B',
    bg: 'rgba(184,134,11,0.08)',
    border: '#B8860B',
  },
  info: {
    label: 'Info',
    color: '#4B44A8',
    bg: 'rgba(75,68,168,0.08)',
    border: '#4B44A8',
  },
  success: {
    label: 'Milestone',
    color: '#0D7A5F',
    bg: 'rgba(13,122,95,0.08)',
    border: '#0D7A5F',
  },
}

export const NUDGE_PRIORITY = { alert: 4, warning: 3, info: 2, success: 1 }

export const MAX_VISIBLE_NUDGES = 2

// Nudge dismissal helpers using sessionStorage
// Dismissed nudges stay dismissed for the session but return on next visit
export const isDismissed = (nudgeId) => {
  try {
    const dismissed = JSON.parse(sessionStorage.getItem('dismissedNudges') || '[]')
    return dismissed.includes(nudgeId)
  } catch {
    return false
  }
}

export const dismissNudge = (nudgeId) => {
  try {
    const dismissed = JSON.parse(sessionStorage.getItem('dismissedNudges') || '[]')
    if (!dismissed.includes(nudgeId)) {
      dismissed.push(nudgeId)
      sessionStorage.setItem('dismissedNudges', JSON.stringify(dismissed))
    }
  } catch {
    // fail silently
  }
}

export const clearDismissed = () => {
  try {
    sessionStorage.removeItem('dismissedNudges')
  } catch {
    // fail silently
  }
}